const StartRun = Schema.TaggedStruct("StartRunFromPlan", { planId: Schema.NonEmptyString, expectedPlanRevision: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)), expectedLeaseRevision: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)), idempotencyKey: Schema.NonEmptyString })
const ControlCommand = Schema.Struct({ expectedLeaseRevision: Schema.Int.check(Schema.isGreaterThanOrEqualTo(0)), expectedRunRevision: Schema.optionalKey(Schema.Int.check(Schema.isGreaterThanOrEqualTo(0))), idempotencyKey: Schema.NonEmptyString })
type Capability = "controlCapable" | "readOnly"
export type LocalIdentity = { readonly personId: string; readonly clientId: string; readonly capability: Capability; readonly role?: "owner" | "viewer" }
export type RequestAdmission = (request?: IncomingMessage) => LocalIdentity | undefined
const AccessClaims = Schema.Struct({ sub: Schema.NonEmptyString, iss: Schema.NonEmptyString, aud: Schema.Union([Schema.NonEmptyString, Schema.Array(Schema.NonEmptyString)]), exp: Schema.Int, email: Schema.optionalKey(Schema.String) })
const AccessHeader = Schema.Struct({ alg: Schema.Literal("RS256"), typ: Schema.optionalKey(Schema.String) })
const MembershipRow = Schema.Struct({ person_id: Schema.String, role: Schema.Literals(["owner", "viewer"]) })
const MembershipBootstrap = Schema.Array(Schema.Struct({ email: Schema.NonEmptyString, personId: Schema.NonEmptyString, role: Schema.Literals(["owner", "viewer"]) }))
const jwtPart = (part: string) => Buffer.from(part, "base64url")
function normalizedEmail(value: string) { const email = value.trim().toLowerCase(); if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error("Bootstrap email is invalid"); return email }
function verifiedAccessClaims(config: { readonly issuer: string; readonly audience: string; readonly publicKeyPem: string }, request: IncomingMessage | undefined) { const token = request?.headers["cf-access-jwt-assertion"]; if (typeof token !== "string" || token.length > 8_192) return undefined; const [encodedHeader, encodedClaims, encodedSignature, extra] = token.split("."); if (!encodedHeader || !encodedClaims || !encodedSignature || extra !== undefined) return undefined; try { const header = Schema.decodeUnknownSync(AccessHeader)(JSON.parse(jwtPart(encodedHeader).toString("utf8"))); const claims = Schema.decodeUnknownSync(AccessClaims)(JSON.parse(jwtPart(encodedClaims).toString("utf8"))); if (header.alg !== "RS256" || claims.iss !== config.issuer || !(Array.isArray(claims.aud) ? claims.aud : [claims.aud]).includes(config.audience) || claims.exp <= Math.floor(Date.now() / 1_000)) return undefined; const verifier = createVerify("RSA-SHA256"); verifier.update(`${encodedHeader}.${encodedClaims}`); verifier.end(); return verifier.verify(config.publicKeyPem, jwtPart(encodedSignature)) ? claims : undefined } catch { return undefined } }
export function createCloudflareAccessAdmission(config: { readonly issuer: string; readonly audience: string; readonly publicKeyPem: string; readonly databasePath: string; readonly clientContext: "desktop" | "phone" }): RequestAdmission { return (request) => { try { const token = request.headers["cf-access-jwt-assertion"]; if (typeof token !== "string" || token.length > 8_192) return undefined; const [encodedHeader, encodedClaims, encodedSignature, extra] = token.split("."); if (encodedHeader === undefined || encodedClaims === undefined || encodedSignature === undefined || extra !== undefined) return undefined; const header = Schema.decodeUnknownSync(AccessHeader)(JSON.parse(jwtPart(encodedHeader).toString("utf8"))); const claims = Schema.decodeUnknownSync(AccessClaims)(JSON.parse(jwtPart(encodedClaims).toString("utf8"))); if (header.alg !== "RS256" || claims.iss !== config.issuer || !(Array.isArray(claims.aud) ? claims.aud : [claims.aud]).includes(config.audience) || claims.exp <= Math.floor(Date.now() / 1_000)) return undefined; const verifier = createVerify("RSA-SHA256"); verifier.update(`${encodedHeader}.${encodedClaims}`); verifier.end(); if (!verifier.verify(config.publicKeyPem, jwtPart(encodedSignature))) return undefined; const membership = new DatabaseSync(config.databasePath); try { const raw: unknown = membership.prepare("SELECT person_id,role FROM memberships WHERE external_subject=?").get(claims.sub); const row = Schema.decodeUnknownSync(Schema.optional(MembershipRow))(raw); return row === undefined ? undefined : { personId: row.person_id, clientId: `access:${claims.sub}`, role: row.role, capability: row.role === "owner" && config.clientContext === "desktop" ? "controlCapable" : "readOnly" } } finally { membership.close() } } catch { return undefined } } }
export function createProductionAccessAdmission(config: { readonly issuer: string; readonly audience: string; readonly publicKeyPem: string; readonly databasePath: string; readonly clientContext: "desktop" | "phone"; readonly bootstrap: ReadonlyArray<{ readonly email: string; readonly personId: string; readonly role: "owner" | "viewer" }> }): RequestAdmission { const policy = config.bootstrap.map((entry) => ({ ...entry, email: normalizedEmail(entry.email) })); if (new Set(policy.map((entry) => entry.email)).size !== policy.length) throw new Error("Bootstrap emails must be unique after normalization"); return (request) => { const claims = verifiedAccessClaims(config, request); if (!claims || claims.email === undefined) return undefined; const entry = policy.find((item) => item.email === normalizedEmail(claims.email)); if (!entry) return undefined; const membership = new DatabaseSync(config.databasePath); try { membership.exec("BEGIN IMMEDIATE"); membership.prepare("INSERT INTO memberships VALUES (?,?,?) ON CONFLICT(external_subject) DO UPDATE SET person_id=excluded.person_id,role=excluded.role").run(claims.sub, entry.personId, entry.role); const raw: unknown = membership.prepare("SELECT person_id,role FROM memberships WHERE external_subject=?").get(claims.sub); const stored = Schema.decodeUnknownSync(MembershipRow)(raw); membership.exec("COMMIT"); if (stored.person_id !== entry.personId || stored.role !== entry.role) return undefined; return { personId: stored.person_id, clientId: `access:${claims.sub}`, role: stored.role, capability: stored.role === "owner" && config.clientContext === "desktop" ? "controlCapable" : "readOnly" } } catch { try { membership.exec("ROLLBACK") } catch {} return undefined } finally { membership.close() } } }
export const createLocalFixtureAdmission = (identity: LocalIdentity): RequestAdmission => () => ({ ...identity, role: identity.role ?? (identity.personId === "owner-chicks" ? "owner" : "viewer") })
export const createSeestarStopStackAdapter = (device: { readonly stopStack: () => Promise<boolean> }) => ({ stopStack: () => device.stopStack() })
export const createSeestarStartStackAdapter = (device: { readonly startStack: () => Promise<boolean> }) => ({ startStack: () => device.startStack() })
type Run = { readonly id: string; readonly revision: number; readonly phase: "capture" | "paused" | "stopped"; readonly target: string; readonly progress: number }
type Evidence = { readonly frameId: string; readonly capturedAt: string; readonly quality: "verified" | "warning"; readonly desired: string; readonly solved: string; readonly uncertaintyArcsec: number; readonly stack: { readonly availability: "available" | "unavailable"; readonly observedAt: string; readonly frameCount: number; readonly message: string }; readonly correction: { readonly state: "automatic" | "exhausted"; readonly evidence: string; readonly bound: string; readonly protection: string; readonly action: string } }
type Snapshot = { readonly snapshotVersion: number; readonly eventCursor: number; readonly generatedAt: string; readonly identity: LocalIdentity; readonly plan: { readonly id: string; readonly revision: number; readonly target: string; readonly readiness: "ready" }; readonly control: { readonly holderClientId: string | null; readonly revision: number; readonly state: "held" | "reconnecting" | "unheld"; readonly reconnectGraceUntil?: string; readonly pendingRequests: ReadonlyArray<{ readonly clientId: string; readonly personId: string }> }; readonly run: Run | null; readonly dispatch: "none" | "pending" | "dispatched" | "unavailable" | "failed"; readonly dispatchAction: "none" | "pause" | "resume" | "stop"; readonly evidence: Evidence; readonly connection: "current" }
type ControlEvent = "ControlRequested" | "ControlGranted" | "OwnerTookControl" | "ControlReconnectGraceStarted" | "ControlReconnected" | "ControlGraceExpired" | "PauseAccepted" | "ResumeAccepted" | "RunStopped"
type FailureReason = "Unauthenticated" | "FreshnessConflict" | "ClientReadOnly" | "ControlLeaseLost" | "OwnerRequired" | "ControlRequestUnavailable" | "ActiveRunConflict" | "InvalidInput"
type CommandResult = { readonly outcome: "accepted"; readonly eventType?: ControlEvent; readonly message?: string; readonly run?: Run; readonly snapshot: Snapshot } | { readonly outcome: "rejected"; readonly reason: FailureReason; readonly message: string }
type LibraryRole = "original" | "linearMaster" | "intermediate" | "final" | "preview" | "diagnostic"
type LibrarySort = "capturedAtDescending" | "sharpestFirst" | "recentlyUpdated"

const StoredEvidence = Schema.Struct({ frameId: Schema.String, capturedAt: Schema.String, quality: Schema.Literals(["verified", "warning"]), desired: Schema.String, solved: Schema.String, uncertaintyArcsec: Schema.Number, stack: Schema.optionalKey(Schema.Struct({ availability: Schema.Literals(["available", "unavailable"]), observedAt: Schema.String, frameCount: Schema.Int, message: Schema.String })), correction: Schema.Struct({ state: Schema.Literals(["automatic", "exhausted"]), evidence: Schema.String, bound: Schema.String, protection: Schema.String, action: Schema.String }) })
const AdapterObservation = Schema.Struct({ frameId: Schema.NonEmptyString, capturedAt: Schema.NonEmptyString, quality: Schema.Literals(["verified", "warning"]), desired: Schema.NonEmptyString, solved: Schema.NonEmptyString, uncertaintyArcsec: Schema.Finite.check(Schema.isGreaterThanOrEqualTo(0)), correctionState: Schema.Literals(["automatic", "exhausted"]), correctionEvidence: Schema.NonEmptyString, correctionBound: Schema.NonEmptyString, protection: Schema.NonEmptyString })
const StoredState = Schema.Struct({ snapshotVersion: Schema.Int, eventCursor: Schema.Int, planRevision: Schema.Int, leaseRevision: Schema.Int, leaseHolder: Schema.NullOr(Schema.String), leaseState: Schema.Literals(["held", "reconnecting", "unheld"]), reconnectGraceUntil: Schema.NullOr(Schema.String), run: Schema.NullOr(Schema.Struct({ id: Schema.String, revision: Schema.Int, phase: Schema.Literals(["capture", "paused", "stopped"]), target: Schema.String, progress: Schema.Number })), evidence: StoredEvidence })
const StoredRequest = Schema.Struct({ client_id: Schema.String, person_id: Schema.String })
const ControlRequestRow = Schema.Struct({ client_id: Schema.String })
const StoredRow = Schema.Struct({ value: Schema.String })
const LatestCursorRow = Schema.Struct({ cursor: Schema.Int })
const MigrationRow = Schema.Struct({ version: Schema.Int })
const OutboxClaimRow = Schema.Struct({ id: Schema.String })
const SqliteColumnRow = Schema.Struct({ name: Schema.String })
const LibraryRole = Schema.Literals(["original", "linearMaster", "intermediate", "final", "preview", "diagnostic"])
const LibrarySort = Schema.Literals(["capturedAtDescending", "sharpestFirst", "recentlyUpdated"])
const LibraryQueryInput = Schema.Struct({ queryId: Schema.NonEmptyString, cursor: Schema.optionalKey(Schema.Int.check(Schema.isGreaterThanOrEqualTo(0))), pageSize: Schema.Int.check(Schema.isGreaterThanOrEqualTo(1), Schema.isLessThanOrEqualTo(100)), role: Schema.optionalKey(LibraryRole), sort: LibrarySort })
const LibraryAssetRow = Schema.Struct({ asset_id: Schema.String, revision: Schema.Int, role: LibraryRole, format: Schema.Literals(["cameraRaw", "fits", "tiff", "png", "jpeg"]), availability: Schema.Literals(["availableLocally", "preparing", "published", "expiring", "expired", "republishing", "temporarilyUnavailable", "failedPublication"]), comparison_group_id: Schema.String, detail: Schema.String })
const LibraryDetail = Schema.Struct({ assetId: Schema.String, revision: Schema.Int, role: LibraryRole, format: Schema.Literals(["cameraRaw", "fits", "tiff", "png", "jpeg"]), availability: Schema.Literals(["availableLocally", "preparing", "published", "expiring", "expired", "republishing", "temporarilyUnavailable", "failedPublication"]), capturedAt: Schema.String, comparisonGroupId: Schema.String, lineage: Schema.Struct({ sourceAssetIds: Schema.Array(Schema.String), runId: Schema.String, solveAttemptId: Schema.String }), representations: Schema.Array(Schema.Struct({ label: Schema.String, state: Schema.String })) })
const PlanWorkspace = Schema.Struct({ planId: Schema.String, revision: Schema.Int, target: Schema.String, readiness: Schema.Literal("ready"), readinessSummary: Schema.String, observingWindow: Schema.Struct({ startsAt: Schema.String, endsAt: Schema.String, usableMinutes: Schema.Int, peakAltitudeDeg: Schema.Number, horizonClearanceDeg: Schema.Number }), sequences: Schema.Array(Schema.Struct({ sequenceId: Schema.String, order: Schema.Int, target: Schema.String, capture: Schema.String, acquisition: Schema.String, stopCondition: Schema.String, viability: Schema.Literal("viable") })) })
const ProcessWorkspace = Schema.Struct({ sessionId: Schema.String, revision: Schema.Int, phase: Schema.Literal("develop"), sourceAssetId: Schema.String, sourceLabel: Schema.String, preview: Schema.Struct({ label: Schema.String, state: Schema.Literal("synchronized"), evidence: Schema.String }), history: Schema.Array(Schema.Struct({ stepId: Schema.String, label: Schema.String, state: Schema.Literals(["applied", "current"]), tool: Schema.String })), checkpoint: Schema.Struct({ stepId: Schema.String, label: Schema.String, protectedBy: Schema.String }), failure: Schema.Struct({ state: Schema.Literal("none"), retryScope: Schema.String }), protection: Schema.String })
const ReceiptRow = Schema.Struct({ response: Schema.String })
const StoredIdentity = Schema.Struct({ personId: Schema.String, clientId: Schema.String, capability: Schema.Literals(["controlCapable", "readOnly"]), role: Schema.optionalKey(Schema.Literals(["owner", "viewer"])) })
const StoredRun = Schema.Struct({ id: Schema.String, revision: Schema.Int, phase: Schema.Literals(["capture", "paused", "stopped"]), target: Schema.String, progress: Schema.Number })
const StoredSnapshot = Schema.Struct({ snapshotVersion: Schema.Int, eventCursor: Schema.Int, generatedAt: Schema.String, identity: StoredIdentity, plan: Schema.Struct({ id: Schema.String, revision: Schema.Int, target: Schema.String, readiness: Schema.Literal("ready") }), control: Schema.Struct({ holderClientId: Schema.NullOr(Schema.String), revision: Schema.Int, state: Schema.Literals(["held", "reconnecting", "unheld"]), reconnectGraceUntil: Schema.optionalKey(Schema.String), pendingRequests: Schema.Array(Schema.Struct({ clientId: Schema.String, personId: Schema.String })) }), run: Schema.NullOr(StoredRun), dispatch: Schema.Literals(["none", "pending", "dispatched", "unavailable", "failed"]), dispatchAction: Schema.Literals(["none", "pause", "resume", "stop"]), evidence: StoredEvidence, connection: Schema.Literal("current") })
const CommandResultSchema = Schema.Union([
  Schema.Struct({ outcome: Schema.Literal("accepted"), eventType: Schema.optionalKey(Schema.Literals(["ControlRequested", "ControlGranted", "OwnerTookControl", "ControlReconnectGraceStarted", "ControlReconnected", "ControlGraceExpired", "PauseAccepted", "ResumeAccepted", "RunStopped"])), message: Schema.optionalKey(Schema.String), run: Schema.optionalKey(StoredRun), snapshot: StoredSnapshot }),
  Schema.Struct({ outcome: Schema.Literal("rejected"), reason: Schema.Literals(["Unauthenticated", "FreshnessConflict", "ClientReadOnly", "ControlLeaseLost", "OwnerRequired", "ControlRequestUnavailable", "ActiveRunConflict", "InvalidInput"]), message: Schema.String }),
])
const operatorMessages = {
  Unauthenticated: "A verified member identity is required.", FreshnessConflict: "The plan changed. Review the current plan before running it.", ClientReadOnly: "Monitoring is read-only on this client.", ControlLeaseLost: "Control changed hands. Your command was not sent to the observatory; the accepted run continues.", OwnerRequired: "Only the owner can grant control.", ControlRequestUnavailable: "There is no current control request to grant.", ActiveRunConflict: "A run is already active. Return to Observe.", InvalidInput: "The service could not read that action.", ControlRequested: "Control request recorded. The owner can grant or decline it.", ControlGranted: "Control granted. The other desktop now owns control.", OwnerTookControl: "Control returned to the owner desktop.", ControlReconnectGraceStarted: "Reconnect grace is active; accepted work continues.", ControlReconnected: "Controller reconnected; control remains current.", ControlGraceExpired: "Reconnect grace expired. Control is unheld; accepted work continues.", PauseAccepted: "Pause was accepted by the service.", ResumeAccepted: "Resume was accepted by the service.", RunStopped: "Stop was accepted by the service. This run cannot be resumed.",
} satisfies Record<FailureReason | ControlEvent, string>

export function createLocalWebService(databasePath = ":memory:", identityResolver: RequestAdmission = createLocalFixtureAdmission({ personId: "owner-chicks", clientId: "desktop-owner", capability: "controlCapable" })) {
  if (databasePath !== ":memory:") mkdirSync(dirname(databasePath), { recursive: true })
  const database = new DatabaseSync(databasePath)
  database.exec("PRAGMA journal_mode = WAL")
  migrateDatabase(database)
  migrateState(database)
  seedLibrary(database)
  seedWorkspaces(database)
  const listeners = new Map<ServerResponse, LocalIdentity>()
  let closed = false
  let emittedCursor = state(database).eventCursor
  const publish = (type: string, cursor: number) => { for (const [response, identity] of listeners) response.write(`id: ${cursor}\nevent: ${type}\ndata: ${JSON.stringify(snapshot(database, identity))}\n\n`) }
  const poll = setInterval(() => { expireReconnectGrace(database); const current = state(database); if (current.eventCursor <= emittedCursor) return; emittedCursor = current.eventCursor; publish("ProjectionChanged", current.eventCursor) }, 250)
  poll.unref()

  const handler = async (request: IncomingMessage, response: ServerResponse) => {
    const url = new URL(request.url ?? "/", "http://local")
    if (request.method === "GET" && url.pathname === "/health/live") return json(response, 200, { status: "alive" })
    expireReconnectGrace(database)
    const identity = identityResolver(request)
    if (request.method === "GET" && url.pathname === "/assets/brand/alignment-aperture-light.svg") return asset(response)
    if (identity === undefined) return json(response, 401, reject("Unauthenticated").body)
    if (request.method === "GET" && url.pathname === "/") return html(response)
    if (request.method === "GET" && url.pathname === "/api/snapshot") return json(response, 200, snapshot(database, identity))
    if (request.method === "GET" && url.pathname === "/api/health/ready") return json(response, 200, readiness(database))
    if (request.method === "GET" && url.pathname === "/api/health/operations") return isOwner(identity) ? json(response, 200, operations(database)) : json(response, 403, reject("OwnerRequired").body)
    if (request.method === "GET" && url.pathname === "/api/events") return stream(request, response, database, identity, listeners)
    if (request.method === "GET" && url.pathname === "/api/workspaces/plan") return workspace(response, database, "plan")
    if (request.method === "GET" && url.pathname === "/api/workspaces/process") return processWorkspace(response, database, url)
    if (request.method === "GET" && url.pathname === "/api/library") return libraryPage(response, database, url)
    if (request.method === "GET" && url.pathname.startsWith("/api/library/assets/")) return libraryDetail(response, database, decodeURIComponent(url.pathname.slice("/api/library/assets/".length)))
    if (request.method === "POST" && url.pathname === "/api/commands/start-run") return runCommand(response, await body(request), database, identity, publish)
    if (request.method === "POST" && controlPaths.has(url.pathname)) return controlCommand(response, await body(request), database, url.pathname, identity, publish)
    response.writeHead(404).end()
  }
  const listen = (port = 0, host = "127.0.0.1") => new Promise<{ readonly port: number; readonly close: () => Promise<void> }>((resolve, reject) => {
    if (!Number.isInteger(port) || port < 0 || port > 65_535) return reject(new Error("Listen port must be an integer from 0 to 65535"))
    if (host !== "127.0.0.1" && host !== "0.0.0.0") return reject(new Error("Listen host must be loopback or the private Compose network"))
    const server = createServer(handler).listen(port, host, () => {
      const address = server.address()
      if (address === null || typeof address === "string") return reject(new Error("Local server did not bind a TCP port"))
      resolve({ port: address.port, close: () => new Promise((done) => server.close(() => done())) })
    })
  })
  const close = () => { if (closed) return; closed = true; clearInterval(poll); database.close() }
  const ingestObservation = (raw: unknown) => { try { const input = Schema.decodeUnknownSync(AdapterObservation)(raw); const current = state(database); const evidence: Evidence = { ...current.evidence, frameId: input.frameId, capturedAt: input.capturedAt, quality: input.quality, desired: input.desired, solved: input.solved, uncertaintyArcsec: input.uncertaintyArcsec, correction: { state: input.correctionState, evidence: input.correctionEvidence, bound: input.correctionBound, protection: input.protection, action: input.correctionState === "automatic" ? "none" : "Review recovery in Observe before any new command." } }; return persistEvidence(database, evidence, () => identityResolver() ?? { personId: "system", clientId: "system", capability: "readOnly" }) } catch { return undefined } }
  const ingestSeestarStackPush = (raw: unknown, receivedAt: string) => { const event = decodeSeestarPushEvent(raw); if (event?.Event !== "Stack" || !Number.isFinite(event.stacked_frame ?? event.stacked_frames)) return undefined; const current = state(database); const failed = event.state?.toLowerCase() === "fail" || event.state?.toLowerCase() === "cancel" || (event.code !== undefined && event.code !== 0); const evidence: Evidence = { ...current.evidence, stack: { availability: failed ? "unavailable" : "available", observedAt: receivedAt, frameCount: event.stacked_frame ?? event.stacked_frames ?? 0, message: failed ? event.error ?? "Stack source unavailable; accepted run state is unchanged." : "Stack event received." }, quality: failed ? "warning" : current.evidence.quality }; return persistEvidence(database, evidence, () => identityResolver() ?? { personId: "system", clientId: "system", capability: "readOnly" }) }
  const dispatch = async (kind: "StopStack" | "ResumeStack" | "StopRun", workerId: string, invoke: (() => Promise<unknown>) | undefined) => { const token = randomUUID(); database.exec("BEGIN IMMEDIATE"); try { database.prepare("UPDATE outbox SET state='failed',claim_token=NULL,claimed_by=NULL,claim_until=NULL,last_error='claim expired',retry_after=? WHERE state='claimed' AND claim_until<=?").run(new Date().toISOString(), new Date().toISOString()); const raw: unknown = database.prepare("SELECT id FROM outbox WHERE kind=? AND state IN ('pending','failed') AND (retry_after IS NULL OR retry_after<=?) ORDER BY CASE state WHEN 'pending' THEN 0 ELSE 1 END,rowid LIMIT 1").get(kind, new Date().toISOString()); const row = Schema.decodeUnknownSync(Schema.optional(OutboxClaimRow))(raw); if (row === undefined) { database.exec("COMMIT"); return "none" as const } const claimed = database.prepare("UPDATE outbox SET state='claimed',claim_token=?,claimed_by=?,claim_until=?,attempts=attempts+1 WHERE id=? AND state IN ('pending','failed')").run(token, workerId, new Date(Date.now() + 30_000).toISOString(), row.id); if (claimed.changes !== 1) { database.exec("COMMIT"); return "none" as const } database.exec("COMMIT"); try { const accepted = invoke === undefined ? false : Schema.decodeUnknownSync(Schema.Boolean)(await invoke()); database.exec("BEGIN IMMEDIATE"); const acknowledged = database.prepare("UPDATE outbox SET state=?,ack_at=?,claim_token=NULL,claimed_by=NULL,claim_until=NULL,last_error=? WHERE id=? AND state='claimed' AND claim_token=?").run(accepted ? "dispatched" : "failed", accepted ? new Date().toISOString() : null, accepted ? null : "adapter rejected work", row.id, token); database.exec("COMMIT"); return acknowledged.changes === 1 ? accepted ? "dispatched" as const : "failed" as const : "superseded" as const } catch { database.exec("BEGIN IMMEDIATE"); const failed = database.prepare("UPDATE outbox SET state='failed',claim_token=NULL,claimed_by=NULL,claim_until=NULL,last_error=?,retry_after=? WHERE id=? AND state='claimed' AND claim_token=?").run("adapter failed", new Date().toISOString(), row.id, token); database.exec("COMMIT"); return failed.changes === 1 ? "failed" as const : "superseded" as const } } catch (error) { database.exec("ROLLBACK"); throw error } }
  const dispatchPauseOutbox = (adapter: { readonly stopStack: () => Promise<unknown> } | undefined, workerId = "pause-worker") => dispatch("StopStack", workerId, adapter === undefined ? undefined : () => adapter.stopStack())
  const dispatchResumeOutbox = (adapter: { readonly startStack: () => Promise<unknown> } | undefined, workerId = "resume-worker") => dispatch("ResumeStack", workerId, adapter === undefined ? undefined : () => adapter.startStack())
  const dispatchStopOutbox = (adapter: { readonly stopStack: () => Promise<unknown> } | undefined, workerId = "stop-worker") => dispatch("StopRun", workerId, adapter === undefined ? undefined : () => adapter.stopStack())
  return { database, handler, listen, close, ingestObservation, ingestSeestarStackPush, dispatchPauseOutbox, dispatchResumeOutbox, dispatchStopOutbox }
}

const controlPaths = new Set(["/api/commands/request-control", "/api/commands/grant-control", "/api/commands/take-control", "/api/commands/controller-disconnected", "/api/commands/controller-reconnected", "/api/commands/pause-run", "/api/commands/resume-run", "/api/commands/stop-run"])
const isOwner = (identity: LocalIdentity) => identity.role === "owner"

function migrateDatabase(db: DatabaseSync) { db.exec("CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL)"); const latestRaw: unknown = db.prepare("SELECT COALESCE(MAX(version), 0) AS version FROM schema_migrations").get(); const latest = Schema.decodeUnknownSync(MigrationRow)(latestRaw).version; const migrations = [() => db.exec("CREATE TABLE IF NOT EXISTS state (key TEXT PRIMARY KEY,value TEXT NOT NULL); CREATE TABLE IF NOT EXISTS events (cursor INTEGER PRIMARY KEY,type TEXT NOT NULL,snapshot TEXT NOT NULL); CREATE TABLE IF NOT EXISTS receipts (idempotency_key TEXT PRIMARY KEY,response TEXT NOT NULL); CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY,kind TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL); CREATE TABLE IF NOT EXISTS control_requests (client_id TEXT PRIMARY KEY,person_id TEXT NOT NULL); CREATE TABLE IF NOT EXISTS memberships (external_subject TEXT PRIMARY KEY,person_id TEXT NOT NULL,role TEXT NOT NULL); CREATE TABLE IF NOT EXISTS library_assets (asset_id TEXT PRIMARY KEY,revision INTEGER NOT NULL,role TEXT NOT NULL,format TEXT NOT NULL,availability TEXT NOT NULL,comparison_group_id TEXT NOT NULL,captured_at TEXT NOT NULL,updated_at TEXT NOT NULL,sharpness REAL NOT NULL,detail TEXT NOT NULL);"), () => migrateOutbox(db), () => db.exec("CREATE TABLE IF NOT EXISTS workspace_projections (name TEXT PRIMARY KEY,value TEXT NOT NULL)")] as const; if (latest > migrations.length) throw new Error(`Database schema ${latest} is newer than this release`); for (let index = latest; index < migrations.length; index += 1) { db.exec("BEGIN IMMEDIATE"); try { migrations[index]?.(); db.prepare("INSERT INTO schema_migrations VALUES (?,?)").run(index + 1, new Date().toISOString()); db.exec("COMMIT") } catch (error) { db.exec("ROLLBACK"); throw error } } }
function migrateOutbox(db: DatabaseSync) { const raw: unknown = db.prepare("PRAGMA table_info(outbox)").all(); const columns = new Set(Schema.decodeUnknownSync(Schema.Array(SqliteColumnRow))(raw).map((column) => column.name)); for (const [name, definition] of [["claim_token", "TEXT"], ["claimed_by", "TEXT"], ["claim_until", "TEXT"], ["attempts", "INTEGER NOT NULL DEFAULT 0"], ["last_error", "TEXT"], ["retry_after", "TEXT"], ["ack_at", "TEXT"]] as const) if (!columns.has(name)) db.exec(`ALTER TABLE outbox ADD COLUMN ${name} ${definition}`) }
