const applicationShell = `<!doctype html><html><head><meta name="viewport" content="width=device-width"><title>Astro Console</title><style>:root{--night:#081014;--cyan:#41c3cf;--sky:#9de8ed;--line:#354851;--text:#e5f0f1;--muted:#9babad;--mono:ui-monospace,monospace}*{box-sizing:border-box}body{margin:0;background:var(--night);color:var(--text);font:14px system-ui}main{max-width:1240px;margin:auto;padding:24px}.anchor{display:grid;grid-template-columns:1fr auto 1fr;gap:18px;align-items:center;border-bottom:1px solid var(--line);padding-bottom:16px}.brand{display:flex;gap:10px;align-items:center;font-size:18px;font-weight:750}.brand img{width:30px}.register{display:flex;gap:20px;color:var(--muted);font:12px var(--mono)}.register b{display:block;color:var(--text)}.truth{justify-self:end;color:var(--sky);font:700 11px var(--mono);letter-spacing:.12em;text-align:right}.truth button{display:block;margin:8px 0 0 auto}.nav{display:flex;gap:8px;margin:16px 0;border-bottom:1px solid var(--line)}button{margin:4px;padding:10px 13px;border:0;border-radius:3px;background:var(--cyan);color:var(--night);font-weight:700}button:focus-visible{outline:2px solid var(--sky);outline-offset:3px}.nav button{background:none;color:var(--muted);font:12px var(--mono)}.nav button[aria-current]{color:var(--sky);border-bottom:2px solid var(--cyan)}.room{display:none;padding:20px;border:1px solid var(--line);border-radius:4px;background:#0d151a}.room.active{display:block}.ey{color:var(--sky);font:11px var(--mono);letter-spacing:.12em;text-transform:uppercase}.facts{display:grid;grid-template-columns:repeat(2,1fr);border:1px solid var(--line)}.facts span{padding:10px;color:var(--muted);font:12px var(--mono)}.facts b{display:block;color:var(--text)}#notice{min-height:22px;color:var(--sky)}#evidence-surface{margin:16px 0}.optical-frame{position:relative;min-height:220px;overflow:hidden;border:1px solid #3a4a57;border-radius:8px;background:radial-gradient(circle at 58% 42%,#17323a 0,#0e141a 35%,#080c10 78%);box-shadow:inset 0 0 0 1px #111920}.optical-frame.exhausted{border-color:#f3bb62;background:radial-gradient(circle at 64% 35%,#332919 0,#0e141a 38%,#080c10 78%)}.geometry{position:absolute;inset:0}.geometry line{stroke:#67d5df;stroke-width:2}.geometry circle{fill:#67d5df}.geometry .solved{fill:none;stroke:#a2f3f4;stroke-width:2}.geometry .uncertainty{fill:none;stroke:#8fb6ff;stroke-dasharray:4 4}.geometry-label{position:absolute;left:12px;bottom:10px;font:12px var(--mono);color:#e9f0f4;background:#0e141acc;padding:6px}.exhausted .geometry-label{color:#f3bb62}#library-results{height:340px;overflow:auto}.library-row{display:block;width:100%;margin:0;background:#111920;color:var(--text);text-align:left;font:12px var(--mono)}@media(max-width:600px){main{padding:16px}.anchor{grid-template-columns:1fr auto}.register{grid-column:1/-1;justify-content:space-between;font-size:10px}.truth{grid-column:2}.facts{grid-template-columns:1fr}}</style></head><body><main><header class="anchor"><div class="brand"><img src="/assets/brand/alignment-aperture-light.svg" alt="Alignment Aperture V1">Astro Console</div><div class="register"><span>Accepted run<b id="runfact">Loading</b></span><span>Controller<b id="controllerfact">Loading</b></span><span>Evidence age<b id="agefact">—</b></span></div><div class="truth">SERVICE TRUTH<button id="return" hidden>Return to Observe</button></div></header><nav class="nav" aria-label="Workspaces"><button data-room="Plan">Plan</button><button data-room="Observe">Observe</button><button data-room="Library">Library</button><button data-room="Process">Process</button></nav><section class="room" id="Plan"><p class="ey">Observing plan · ready</p><h1>M27 · Dumbbell Nebula</h1><div class="facts"><span>Sequence<b>24 × 180s · L</b></span><span>Window<b>23:18–01:02</b></span></div><div id="plan-actions"></div></section><section class="room" id="Observe"><p class="ey">Observe attention · owner: Observe</p><h1 id="observe-title">No active run</h1><p id="authority"></p><section id="evidence-surface"><p class="ey">Latest evidence · service owned</p><div id="optical-frame" class="optical-frame" role="img" aria-labelledby="evidence-frame evidence-geometry"><svg class="geometry" viewBox="0 0 640 260" preserveAspectRatio="none" aria-hidden="true"><line x1="320" y1="130" x2="380" y2="100"></line><circle cx="320" cy="130" r="5"></circle><circle class="solved" cx="380" cy="100" r="8"></circle><circle class="uncertainty" cx="380" cy="100" r="22"></circle></svg><div id="evidence-geometry" class="geometry-label">Desired center to solved center; uncertainty ring</div></div><h2 id="evidence-frame">Loading frame</h2><div class="facts"><span>Desired<b id="evidence-desired"></b></span><span>Solved<b id="evidence-solved"></b></span><span>Uncertainty<b id="evidence-uncertainty"></b></span><span>Stack source<b id="stack-source"></b></span></div><p id="stack-trace" role="status"></p><p id="correction-trace"></p><p id="correction-protection"></p><p id="pause-dispatch" role="status"></p></section><p id="pause-consequence" role="status"></p><div id="control-actions"></div><p id="notice" role="status"></p></section><section class="room" id="Library"><p class="ey">Library chronology · bounded page</p><h1>Captured evidence and lineage</h1><p>Only a bounded page is installed. Select an asset for availability and immutable provenance.</p><div><button id="library-prev" aria-label="Previous Library results window" disabled>Previous assets</button><button id="library-next" aria-label="Next Library results window" disabled>Next assets</button></div><div id="library-results" aria-label="Library results"></div><aside id="library-detail" aria-live="polite">Select an asset to inspect its lineage.</aside></section><section class="room" id="Process"><p class="ey">Process</p><h1>Processing is not yet installed</h1></section></main><script>let projection;const q=s=>document.querySelector(s),nav=[...document.querySelectorAll('[data-room]')],library={results:[],start:0},libraryNode=q('#library-results'),libraryDetailNode=q('#library-detail'),libraryPrev=q('#library-prev'),libraryNext=q('#library-next');function select(room){nav.forEach(x=>x.toggleAttribute('aria-current',x.dataset.room===room));document.querySelectorAll('.room').forEach(x=>x.classList.toggle('active',x.id===room))}nav.forEach(x=>x.onclick=()=>select(x.dataset.room));q('#return').onclick=()=>select('Observe');function text(node,value){node.textContent=value}async function send(path,payload){const v=await fetch(path,{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(payload)}).then(r=>r.json());text(q('#notice'),v.message||'The service did not accept this action.');if(v.snapshot)render(v.snapshot)}function control(path){return send(path,{expectedLeaseRevision:projection.control.revision,idempotencyKey:crypto.randomUUID()})}function action(label,fn){const b=document.createElement('button');text(b,label);b.onclick=fn;return b}function render(s){projection=s;q('#return').hidden=!s.run;text(q('#runfact'),s.run?'M27 · '+s.run.phase:'No run');text(q('#controllerfact'),s.control.holderClientId);text(q('#agefact'),'current');text(q('#observe-title'),s.run?s.run.phase==='stopped'?'Stopped · M27 will not resume':s.run.phase==='paused'?'Paused · M27 awaits Resume':'Capture · M27 is continuing':'No active run');text(q('#authority'),'Lease '+s.control.state+' · controller '+s.control.holderClientId);q('#optical-frame').classList.toggle('exhausted',s.evidence.correction.state==='exhausted');text(q('#evidence-frame'),s.evidence.frameId+' · '+s.evidence.quality+' · '+s.evidence.capturedAt);text(q('#evidence-geometry'),'Desired '+s.evidence.desired+' to solved '+s.evidence.solved+'; uncertainty '+s.evidence.uncertaintyArcsec+' arcsec.');text(q('#evidence-desired'),s.evidence.desired);text(q('#evidence-solved'),s.evidence.solved);text(q('#evidence-uncertainty'),s.evidence.uncertaintyArcsec+' arcsec');const stack=s.evidence.stack;text(q('#stack-source'),stack?stack.availability+' · '+stack.frameCount+' frames':'not observed');text(q('#stack-trace'),stack?('Stack observed '+stack.observedAt+' · '+stack.message):'No Stack observation has been received.');text(q('#correction-trace'),s.evidence.correction.state+' correction · '+s.evidence.correction.evidence+' '+s.evidence.correction.bound);const correctionProtection=s.run?.phase==='stopped'?'Latest solve evidence is preserved. This run is terminally stopped; no automatic correction or capture will continue.':s.run?.phase==='paused'?'Latest solve evidence is preserved while capture is paused. No automatic correction or capture will continue until Resume is accepted.':s.run?.phase==='capture'?s.evidence.correction.protection:'Latest solve evidence is retained; no active capture is running.';text(q('#correction-protection'),correctionProtection);text(q('#pause-dispatch'),s.dispatch==='none'?'':s.dispatchAction==='stop'?(s.dispatch==='pending'?'Stop accepted; Seestar stop-stack dispatch is pending.':s.dispatch==='dispatched'?'Stop accepted; terminal stop-stack dispatch completed.':s.dispatch==='unavailable'?'Stop accepted; stop-stack adapter is unavailable. The run remains terminally stopped.':'Stop accepted; stop-stack dispatch failed. The run remains terminally stopped; review adapter recovery.'):s.dispatchAction==='resume'?(s.dispatch==='pending'?'Resume accepted; Seestar start-stack dispatch is pending.':s.dispatch==='dispatched'?'Resume accepted; start-stack dispatch completed.':s.dispatch==='unavailable'?'Resume accepted; start-stack adapter is unavailable. Capture remains resumed safely.':'Resume accepted; start-stack dispatch failed. Capture remains resumed; review adapter recovery.'):(s.dispatch==='pending'?'Pause accepted; Seestar stop-stack dispatch is pending.':s.dispatch==='dispatched'?'Pause accepted; stop-stack dispatch completed.':s.dispatch==='unavailable'?'Pause accepted; stop-stack adapter is unavailable. Capture remains paused safely.':'Pause accepted; stop-stack dispatch failed. Capture remains paused; review adapter recovery.'));const plan=q('#plan-actions'),controls=q('#control-actions');text(q('#pause-consequence'),s.identity.capability==='controlCapable'&&s.run?.phase==='capture'&&s.control.holderClientId===s.identity.clientId?'Pause accepts resumable capture and requests Seestar stop-stack. If dispatch is unavailable or fails, the accepted paused run remains safely preserved and this trace explains it.':s.identity.capability==='controlCapable'&&s.run?.phase==='paused'&&s.control.holderClientId===s.identity.clientId?'Resume restores capture and requests Seestar start-stack. If dispatch is unavailable or fails, the accepted resumed run remains preserved and this trace explains it.':s.identity.capability==='controlCapable'&&s.run?.phase!=='stopped'&&s.control.holderClientId===s.identity.clientId?'Stop is terminal: M27 cannot be resumed. It records the stop before requesting Seestar stop-stack; an unavailable or failed dispatch does not make this run resumable.':s.run?.phase==='stopped'?'This run is terminally stopped and cannot be resumed. Review the stop-stack trace before creating a future run.':'');plan.replaceChildren();controls.replaceChildren();if(s.identity.capability==='readOnly')return;if(!s.run)plan.append(action('Run plan',()=>send('/api/commands/start-run',{_tag:'StartRunFromPlan',planId:'plan-m27',expectedPlanRevision:s.plan.revision,expectedLeaseRevision:s.control.revision,idempotencyKey:crypto.randomUUID()})));if(s.identity.role==='owner'){controls.append(action('Grant control',()=>control('/api/commands/grant-control')),action('Take control',()=>control('/api/commands/take-control')));if(s.run&&s.run.phase==='capture'&&s.control.holderClientId===s.identity.clientId)controls.append(action('Pause capture',()=>send('/api/commands/pause-run',{expectedLeaseRevision:s.control.revision,expectedRunRevision:s.run.revision,idempotencyKey:crypto.randomUUID()})));if(s.run&&s.run.phase==='paused'&&s.control.holderClientId===s.identity.clientId)controls.append(action('Resume capture',()=>send('/api/commands/resume-run',{expectedLeaseRevision:s.control.revision,expectedRunRevision:s.run.revision,idempotencyKey:crypto.randomUUID()})));if(s.run&&s.run.phase!=='stopped'&&s.control.holderClientId===s.identity.clientId)controls.append(action('Stop run',()=>send('/api/commands/stop-run',{expectedLeaseRevision:s.control.revision,expectedRunRevision:s.run.revision,idempotencyKey:crypto.randomUUID()})))}else controls.append(action('Request control',()=>control('/api/commands/request-control')))}function libraryRow(asset){const row=action(asset.role+' · '+asset.format+' · '+asset.availability+' · '+asset.assetId,async()=>{const detail=await fetch('/api/library/assets/'+encodeURIComponent(asset.assetId)).then(response=>response.json());text(libraryDetailNode,'Availability: '+detail.availability+' · Lineage: '+detail.lineage.sourceAssetIds.join(', ')+' · Run: '+detail.lineage.runId+' · Solve: '+detail.lineage.solveAttemptId)});row.className='library-row';return row}function renderLibraryWindow(){libraryNode.replaceChildren();const end=Math.min(library.results.length,library.start+12),spacer=document.createElement('div'),tail=document.createElement('div');spacer.style.height=(library.start*34)+'px';tail.style.height=((library.results.length-end)*34)+'px';libraryNode.append(spacer,...library.results.slice(library.start,end).map(libraryRow),tail);libraryPrev.disabled=library.start===0;libraryNext.disabled=end===library.results.length}async function loadLibrary(){if(library.results.length)return;const page=await fetch('/api/library?queryId=library-m27&pageSize=40&sort=capturedAtDescending').then(response=>response.json());library.results=page.results;renderLibraryWindow()}libraryNode.onscroll=()=>{const next=Math.max(0,Math.floor(libraryNode.scrollTop/34)-2);if(next!==library.start){library.start=next;renderLibraryWindow()}};libraryPrev.onclick=()=>{library.start=Math.max(0,library.start-10);renderLibraryWindow()};libraryNext.onclick=()=>{library.start=Math.min(Math.max(0,library.results.length-1),library.start+10);renderLibraryWindow()};q('[data-room="Library"]').addEventListener('click',loadLibrary);async function load(){render(await fetch('/api/snapshot').then(r=>r.json()));select('Plan');const e=new EventSource('/api/events');['snapshot','RunStarted','ProjectionChanged'].forEach(type=>e.addEventListener(type,event=>render(JSON.parse(event.data))))}load()</script></body></html>`

export function configuredListenPort(value: string | undefined) { if (value === undefined) return 0; if (!/^\d+$/.test(value)) throw new Error("ASTRO_LOCAL_WEB_PORT must be an integer from 0 to 65535"); const port = Number(value); if (port > 65_535) throw new Error("ASTRO_LOCAL_WEB_PORT must be an integer from 0 to 65535"); return port }
export function configuredListenHost(value: string | undefined) { if (value === undefined) return "127.0.0.1" as const; if (value === "127.0.0.1" || value === "0.0.0.0") return value; throw new Error("ASTRO_LOCAL_WEB_BIND must be 127.0.0.1 or 0.0.0.0") }
export function configuredRuntime(env: Record<string, string | undefined>) { const databasePath = env.ASTRO_LOCAL_WEB_DB ?? "./.astro-local-web/state.sqlite"; const release = env.ASTRO_RELEASE ?? "local-web-fixture"; if (!databasePath || /[\r\n]/.test(databasePath) || !release || /[\r\n]/.test(release)) throw new Error("Runtime configuration contains an invalid non-secret value"); return { databasePath, release, port: configuredListenPort(env.ASTRO_LOCAL_WEB_PORT), host: configuredListenHost(env.ASTRO_LOCAL_WEB_BIND) } }
export function configuredAdmission(env: Record<string, string | undefined>, databasePath: string): RequestAdmission { const mode = env.ASTRO_ADMISSION_MODE ?? "development"; if (mode === "development") { if (configuredListenHost(env.ASTRO_LOCAL_WEB_BIND) !== "127.0.0.1") throw new Error("Fixture admission requires loopback development binding"); const client = env.ASTRO_LOCAL_WEB_CLIENT ?? "owner"; return createLocalFixtureAdmission({ personId: client === "friend" ? "friend-ada" : "owner-chicks", clientId: client === "phone" ? "phone-monitor" : client === "friend" ? "desktop-ada" : "desktop-owner", capability: client === "phone" ? "readOnly" : "controlCapable" }) } if (mode !== "production") throw new Error("ASTRO_ADMISSION_MODE must be development or production"); const issuer = env.CF_ACCESS_ISSUER; const audience = env.CF_ACCESS_AUDIENCE; const keyPath = env.CF_ACCESS_PUBLIC_KEY_PATH; const bootstrapPath = env.ASTRO_MEMBERSHIP_BOOTSTRAP_PATH; const clientContext = env.ASTRO_CLIENT_CONTEXT; if (!issuer || !audience || !keyPath || !bootstrapPath || (clientContext !== "desktop" && clientContext !== "phone")) throw new Error("Production admission requires Access issuer, audience, public key path, bootstrap path, and client context"); const bootstrap = Schema.decodeUnknownSync(MembershipBootstrap)(JSON.parse(readFileSync(bootstrapPath, "utf8"))); return createProductionAccessAdmission({ issuer, audience, publicKeyPem: readFileSync(keyPath, "utf8"), databasePath, clientContext, bootstrap }) }
if (process.argv[1]?.endsWith("server.ts")) { const runtime = configuredRuntime(process.env); const service = createLocalWebService(runtime.databasePath, configuredAdmission(process.env, runtime.databasePath)); service.listen(runtime.port, runtime.host).then(({ port }) => console.log(`Astro Console ${runtime.release}: http://127.0.0.1:${port}`)) }
